// The drift gate (docs ADR-0003): every case set authored here must equal the core's generated list,
// exactly, or the build fails. Case-set prose lives above; membership lives in the core.
function assertCaseSet(label: string, authored: string[], generated: string[]): void {
  const normalize = (value: string) => value.replace(/\{.*$/, '');
  const mine = authored.map(normalize);
  const missing = generated.filter(c => !mine.includes(c));
  const extra = mine.filter(c => !generated.includes(c));
  if (missing.length || extra.length) {
    throw new Error(
      `Shared Facts drift in ${label}: missing from the docs [${missing}], not in the core's generated list [${extra}]. ` +
        `Update src/facts/shared-facts.ts to match the vendored core export (src/facts/upstream/shared-facts.json).`,
    );
  }
}

