assertCaseSet('deliveryIssues', sharedFacts.deliveryIssues.map(c => c.id), upstream.deliveryIssues);
for (const set of sharedFacts.valueSets) {
  const generated =
    set.id === 'status' ? upstream.statuses
    : set.id === 'statusReason' ? upstream.statusReasons
    : set.id === 'connection' ? upstream.connectionStates
    : set.id === 'unreadableReason' ? upstream.unreadableReasons
    : set.id === 'sendFailedReason' ? upstream.sendFailedReasons
    : set.id === 'admissionDroppedReason' ? upstream.admissionDropReasons
    : undefined;
  if (generated) assertCaseSet(`valueSets/${set.id}`, set.values, generated);
}
